using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in 9.0.
        // Fix: Explicitly restore the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|KeyValue" to just "KeyValue" in 9.0.
        // Fix: Explicitly configure the old id format using HasJsonIdProperty (not needed here since
        // we override the id property directly). Use the legacy id factory to keep reading old docs.
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id");

        // Breaking change 3: HasIndex() now throws for Cosmos provider in 9.0 (indexes are not supported).
        // Fix: Remove the HasIndex call entirely.
        // (Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

